<template><section class="content-card"><div class="page-title"><div><p class="eyebrow">ЛИЧНЫЙ КАБИНЕТ</p><h1>Мои записи</h1><p>История и предстоящие посещения салона.</p></div><Button label="Новая запись" icon="pi pi-plus" @click="$router.push('/booking')"/></div><div v-if="!items.length" class="empty-state"><i class="pi pi-calendar"></i><h3>Записей пока нет</h3><p>Выберите услугу и удобное время.</p></div><div v-else class="appointment-list"><article v-for="item in items" :key="item.id"><div class="date-box"><b>{{day(item.data_vremya)}}</b><span>{{month(item.data_vremya)}}</span></div><div><h3>{{item.vybrannaya_usluga?.nazvanie||'Услуга'}}</h3><p>{{item.kosmetolog?.fio}} · {{time(item.data_vremya)}}</p></div><Tag :value="status(item.status).label" :severity="status(item.status).severity"/></article></div></section></template>
<script>import Button from 'primevue/button';import Tag from 'primevue/tag';import {useDataStore} from '@/stores/dataStore';export default{components:{Button,Tag},data:()=>({store:useDataStore(),items:[]}),async mounted(){this.items=await this.store.get_my_bookings()},methods:{day(v){return new Date(v).getDate()},month(v){return new Date(v).toLocaleDateString('ru-RU',{month:'short'})},time(v){return new Date(v).toLocaleTimeString('ru-RU',{hour:'2-digit',minute:'2-digit'})},status(v){return{new:{label:'Новая',severity:'warn'},confirmed:{label:'Подтверждена',severity:'success'},completed:{label:'Завершена',severity:'info'},cancelled:{label:'Отменена',severity:'danger'}}[v]||{label:v}}}}</script>
